/* ============ UTIL ============ */
function shuffle(arr){
  const a = arr.slice();
  for(let i=a.length-1;i>0;i--){
    const j = Math.floor(Math.random()*(i+1));
    [a[i],a[j]] = [a[j],a[i]];
  }
  return a;
}
function formatTime(seconds){
  if(!Number.isFinite(seconds)||seconds<0) return '0:00';
  const m = Math.floor(seconds/60);
  const s = Math.floor(seconds%60).toString().padStart(2,'0');
  return m+':'+s;
}
function slugify(name){
  let base = name.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'') || 'album';
  if(base==='all') base='album';
  let id = base, n=2;
  while(state.categories[id] || state.deletedCategoryIds.has(id)){ id = base+'-'+n; n++; }
  return id;
}
function uid(){ return 'i-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8); }
function escapeHTML(s){
  const d = document.createElement('div');
  d.textContent = s;
  return d.innerHTML;
}
let toastTimer=null;
function showToast(msg){
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=>t.classList.remove('show'), 2600);
}

/* ============ INDEXEDDB ============ */
const DB_NAME='memoryWallDB', DB_VERSION=2;
let dbPromise=null;
function openDB(){
  if(dbPromise) return dbPromise;
  dbPromise = new Promise((resolve)=>{
    if(!('indexedDB' in window)){ resolve(null); return; }
    let req;
    try{ req = indexedDB.open(DB_NAME, DB_VERSION); }catch(e){ resolve(null); return; }
    req.onupgradeneeded = (e)=>{
      const db = e.target.result;
      if(!db.objectStoreNames.contains('items')) db.createObjectStore('items',{keyPath:'id'});
      if(!db.objectStoreNames.contains('categories')) db.createObjectStore('categories',{keyPath:'id'});
      if(!db.objectStoreNames.contains('deletedSeeds')) db.createObjectStore('deletedSeeds',{keyPath:'id'});
    };
    req.onsuccess = ()=> resolve(req.result);
    req.onerror = ()=> resolve(null);
    req.onblocked = ()=> resolve(null);
  });
  return dbPromise;
}
async function idbGetAll(storeName){
  const db = await openDB();
  if(!db) return [];
  return new Promise((resolve)=>{
    try{
      const tx = db.transaction(storeName,'readonly');
      const req = tx.objectStore(storeName).getAll();
      req.onsuccess = ()=> resolve(req.result||[]);
      req.onerror = ()=> resolve([]);
    }catch(e){ resolve([]); }
  });
}
async function idbPut(storeName, obj){
  const db = await openDB();
  if(!db) return false;
  return new Promise((resolve)=>{
    try{
      const tx = db.transaction(storeName,'readwrite');
      tx.objectStore(storeName).put(obj);
      tx.oncomplete = ()=> resolve(true);
      tx.onerror = ()=> resolve(false);
    }catch(e){ resolve(false); }
  });
}
async function idbDelete(storeName, id){
  const db = await openDB();
  if(!db) return false;
  return new Promise((resolve)=>{
    try{
      const tx = db.transaction(storeName,'readwrite');
      tx.objectStore(storeName).delete(id);
      tx.oncomplete = ()=> resolve(true);
      tx.onerror = ()=> resolve(false);
    }catch(e){ resolve(false); }
  });
}

/* ============ SEED / STATE INIT ============ */
function buildSeedState(){
  CATEGORY_SEED.forEach(c=> state.categories[c.id]=c.label);
  SEED_PHOTOS.forEach((p,i)=>{
    state.items.push({id:'seed-photo-'+(i+1), type:'photo', src:p.src, categories:p.categories||[], caption:p.caption||'', isSeed:true});
  });
  if(SEED_VIDEO){
    state.items.push({id:'seed-video-1', type:'video', src:SEED_VIDEO.src, categories:SEED_VIDEO.categories||[], caption:SEED_VIDEO.caption||'Our little video ♡', isSeed:true});
  }
}
async function loadUploaded(){
  const [items, cats, deletedSeeds] = await Promise.all([idbGetAll('items'), idbGetAll('categories'), idbGetAll('deletedSeeds')]);
  let changed = false;
  cats.forEach(c=>{
    if(c.deleted){
      state.deletedCategoryIds.add(c.id);
      if(state.categories[c.id]){ delete state.categories[c.id]; changed=true; }
      return;
    }
    if(!state.categories[c.id] && !state.deletedCategoryIds.has(c.id)){ state.categories[c.id]=c.label; changed=true; }
  });
  if(state.deletedCategoryIds.size){
    state.items.forEach(i=>{
      if(i.categories && i.categories.some(c=>state.deletedCategoryIds.has(c))) i.categories = i.categories.filter(c=>!state.deletedCategoryIds.has(c));
    });
  }
  if(deletedSeeds.length){
    const deletedIds = new Set(deletedSeeds.map(d=>d.id));
    const before = state.items.length;
    state.items = state.items.filter(i=> !(i.isSeed && deletedIds.has(i.id)));
    if(state.items.length !== before) changed = true;
  }
  items.sort((a,b)=> (a.addedAt||0)-(b.addedAt||0));
  items.forEach(it=>{
    if(state.items.some(x=>x.id===it.id)) return;
    let url;
    try{ url = URL.createObjectURL(it.blob); }catch(e){ return; }
    state.items.push({id:it.id, type:it.type, src:url, categories:(it.categories||[]).filter(c=>!state.deletedCategoryIds.has(c)), caption:it.caption||'', isSeed:false});
    changed = true;
  });
  if(changed){
    renderFilters();
    renderGrid();
    updateCountBadge();
    refreshFeaturedPool();
  }
}

/* ============ ALBUM CREATION ============ */
async function createAlbum(name){
  name = (name||'').trim();
  if(!name) return null;
  const id = slugify(name);
  state.categories[id] = name;
  await idbPut('categories', {id, label:name, createdAt:Date.now()});
  renderFilters();
  if(document.getElementById('uploadModal').classList.contains('open')) renderUploadChips();
  return id;
}

/* ============ CONFIRM MODAL (replaces window.confirm, which is silently blocked in sandboxed iframes) ============ */
let confirmResolve = null;
function showConfirm(message){
  return new Promise((resolve)=>{
    confirmResolve = resolve;
    document.getElementById('confirmMessage').textContent = message;
    const m = document.getElementById('confirmModal');
    m.classList.add('open');
    m.setAttribute('aria-hidden','false');
    document.body.classList.add('modal-open');
  });
}
function closeConfirm(result){
  const m = document.getElementById('confirmModal');
  if(!m.classList.contains('open')) return;
  m.classList.remove('open');
  m.setAttribute('aria-hidden','true');
  document.body.classList.remove('modal-open');
  const r = confirmResolve;
  confirmResolve = null;
  if(r) r(result);
}

/* ============ DELETE ============ */
async function deleteItem(item){
  if(!item) return;
  const ok = await showConfirm("Delete this memory? This can't be undone.");
  if(!ok) return;
  if(item.isSeed){
    await idbPut('deletedSeeds', {id:item.id, deletedAt:Date.now()});
  } else {
    await idbDelete('items', item.id);
  }
  state.items = state.items.filter(i=>i.id!==item.id);

  const lb = document.getElementById('lightbox');
  const inLightbox = lb.classList.contains('open') && state.lbList[state.lbIndex] && state.lbList[state.lbIndex].id===item.id;

  renderFilters();
  renderGrid();
  updateCountBadge();
  refreshFeaturedPool();
  if(featuredPool.length) setFeatured(state.order[0]);

  if(inLightbox){
    const newList = state.lbList.filter(i=>i.id!==item.id);
    if(newList.length===0){ closeLightbox(); }
    else {
      state.lbIndex = Math.min(state.lbIndex, newList.length-1);
      state.lbList = newList;
      renderLightbox();
    }
  }
  showToast('Memory deleted 🗑');
}

/* ============ DELETE ALBUM ============ */
/* Removes the album itself. The dialog lets you keep its memories on the wall (default) or delete them too.
   Nothing here can touch the lock-screen overlay: that video is its own constant (LOCK_OVERLAY_SRC),
   never part of state.items and never stored in the database. */
let albumDeleteResolve = null;
function askAlbumDelete(id, label){
  const inAlbum = state.items.filter(i=>(i.categories||[]).includes(id));
  const n = inAlbum.length;
  const shared = inAlbum.filter(i=>(i.categories||[]).some(c=>c!==id && state.categories[c])).length;
  const only = document.getElementById('albumDeleteOnly');
  const all = document.getElementById('albumDeleteAll');
  document.getElementById('albumDeleteTitle').textContent = 'Delete the album \u201c'+label+'\u201d?';
  if(n===0){
    document.getElementById('albumDeleteMessage').textContent = 'This album is empty. Nothing else on the wall changes.';
    only.textContent = 'Delete album';
    only.className = 'confirm-btn confirm-danger';
    all.style.display = 'none';
  } else {
    let msg = (n===1 ? '1 memory is' : n+' memories are')+' in this album. Keep '+(n===1?'it':'them')+' on the wall, or delete '+(n===1?'it':'them')+' too?';
    if(shared) msg += ' '+(shared===1 ? '1 also belongs' : shared+' also belong')+' to another album.';
    document.getElementById('albumDeleteMessage').textContent = msg;
    only.textContent = 'Delete album, keep memories';
    only.className = 'confirm-btn confirm-dark';
    all.textContent = n===1 ? 'Delete album and memory' : 'Delete album and all '+n+' memories';
    all.style.display = '';
  }
  return new Promise(resolve=>{
    albumDeleteResolve = resolve;
    const m = document.getElementById('albumDeleteModal');
    m.classList.add('open');
    m.setAttribute('aria-hidden','false');
    document.body.classList.add('modal-open');
    document.getElementById('albumDeleteCancel').focus();
  });
}
function closeAlbumDelete(choice){
  const m = document.getElementById('albumDeleteModal');
  if(!m.classList.contains('open')) return;
  m.classList.remove('open');
  m.setAttribute('aria-hidden','true');
  document.body.classList.remove('modal-open');
  const r = albumDeleteResolve;
  albumDeleteResolve = null;
  if(r) r(choice);
}
async function deleteAlbum(id){
  const label = state.categories[id];
  if(!label) return;
  const choice = await askAlbumDelete(id, label);
  if(!choice) return;
  const inAlbum = state.items.filter(i=>(i.categories||[]).includes(id));
  if(choice==='all'){
    for(const item of inAlbum){
      if(item.isSeed) await idbPut('deletedSeeds', {id:item.id, deletedAt:Date.now()});
      else await idbDelete('items', item.id);
    }
    const gone = new Set(inAlbum.map(i=>i.id));
    state.items = state.items.filter(i=>!gone.has(i.id));
  }
  /* The album is recorded as deleted (not just removed) so its id is never reused,
     which also keeps the built-in albums deleted after a reload. */
  delete state.categories[id];
  state.deletedCategoryIds.add(id);
  state.uploadCats.delete(id);
  state.items.forEach(i=>{ if(i.categories && i.categories.includes(id)) i.categories = i.categories.filter(c=>c!==id); });
  await idbPut('categories', {id, label, deleted:true, deletedAt:Date.now()});
  if(state.activeFilter===id) state.activeFilter = 'all';
  renderFilters();
  renderGrid();
  updateCountBadge();
  refreshFeaturedPool();
  if(featuredPool.length) setFeatured(state.order[0]);
  const first = document.querySelector('#memoryFilters .memory-filter');
  if(first) first.focus();
  const nGone = choice==='all' ? inAlbum.length : 0;
  showToast(nGone ? 'Album and '+nGone+(nGone===1?' memory':' memories')+' deleted \ud83d\uddd1' : 'Album deleted \ud83d\uddd1');
}

/* ============ RENDER: FILTERS ============ */
function itemMatchesFilter(item, filter){
  return filter==='all' || (item.categories||[]).includes(filter);
}
const TRASH_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/></svg>';
function makeFilterPill(id,label,count){
  const b = document.createElement('button');
  b.className = 'memory-filter'+(state.activeFilter===id?' active':'');
  b.type='button';
  b.append(label+' ');
  const span = document.createElement('span');
  span.className='count';
  span.textContent = '\u00b7 '+count;
  b.appendChild(span);
  let group = null;
  if(id!=='all'){
    group = document.createElement('span');
    group.className = 'filter-group'+(state.activeFilter===id?' is-active':'');
    group.appendChild(b);
    const del = document.createElement('button');
    del.type='button';
    del.className='filter-delete';
    del.title='Delete album';
    del.setAttribute('aria-label','Delete album '+label);
    del.innerHTML = TRASH_SVG;
    del.addEventListener('click', (e)=>{ e.stopPropagation(); deleteAlbum(id); });
    group.appendChild(del);
  }
  b.addEventListener('click', ()=>{
    state.activeFilter = id;
    document.querySelectorAll('.memory-filter').forEach(x=>x.classList.remove('active'));
    document.querySelectorAll('.filter-group').forEach(x=>x.classList.remove('is-active'));
    b.classList.add('active');
    if(group) group.classList.add('is-active');
    renderGrid();
  });
  return group || b;
}
function renderFilters(){
  const wrap = document.getElementById('memoryFilters');
  wrap.innerHTML='';
  wrap.appendChild(makeFilterPill('all','All', state.items.length));
  Object.keys(state.categories).forEach(id=>{
    const count = state.items.filter(i=>(i.categories||[]).includes(id)).length;
    wrap.appendChild(makeFilterPill(id, state.categories[id], count));
  });
  const addBtn = document.createElement('button');
  addBtn.className='memory-filter filter-add';
  addBtn.type='button';
  addBtn.textContent='+ New album';
  addBtn.addEventListener('click', ()=>{
    document.getElementById('newAlbumRow').style.display='flex';
    document.getElementById('newAlbumInput').focus();
  });
  wrap.appendChild(addBtn);
}

/* ============ RENDER: GRID ============ */
function renderGrid(){
  const grid = document.getElementById('photoGrid');
  grid.innerHTML='';
  const visible = state.items.filter(i=>itemMatchesFilter(i,state.activeFilter));
  if(visible.length===0){
    const empty = document.createElement('div');
    empty.className='grid-empty';
    const strong = document.createElement('strong');
    strong.textContent='No memories here yet';
    empty.appendChild(strong);
    empty.append('Add one to start this album.');
    grid.appendChild(empty);
    return;
  }
  visible.forEach((item)=>{
    const btn = document.createElement('button');
    btn.type='button';
    btn.className='photo-item'+(lastAddedIds.has(item.id)?' pop-in':'');
    if(item.type==='video'){
      const v = document.createElement('video');
      v.src = item.src; v.muted=true; v.playsInline=true; v.preload='metadata';
      btn.appendChild(v);
      const badge = document.createElement('span');
      badge.className='video-badge';
      badge.innerHTML='<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>';
      btn.appendChild(badge);
    } else {
      const img = document.createElement('img');
      img.src = item.src; img.loading='lazy'; img.alt = item.caption || 'A memory';
      btn.appendChild(img);
    }
    if(item.categories && item.categories.length){
      const catWrap = document.createElement('div');
      catWrap.className='item-cats';
      item.categories.forEach(cid=>{
        if(!state.categories[cid]) return;
        const tag = document.createElement('span');
        tag.textContent = state.categories[cid];
        catWrap.appendChild(tag);
      });
      btn.appendChild(catWrap);
    }
    const delBtn = document.createElement('button');
    delBtn.type='button';
    delBtn.className='item-delete';
    delBtn.setAttribute('aria-label','Delete this memory');
    delBtn.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/></svg>';
    delBtn.addEventListener('click', (e)=>{ e.stopPropagation(); deleteItem(item); });
    btn.appendChild(delBtn);
    btn.addEventListener('click', ()=> openLightbox(visible, visible.indexOf(item)));
    grid.appendChild(btn);
  });
  lastAddedIds.clear();
}
function updateCountBadge(){
  const n = state.items.length;
  document.getElementById('photoCountBadge').textContent = n + (n===1?' memory ♡':' memories ♡');
  document.getElementById('heroSub').textContent = 'Here '+(n===1?'is our memory':'are our little memories')+' I kept for you.';
}

/* ============ RENDER: NOTES ============ */
function renderNotes(){
  const grid = document.getElementById('notesGrid');
  grid.innerHTML='';
  NOTES_SEED.forEach(n=>{
    const b = document.createElement('button');
    b.type='button';
    b.className='square-note '+n.cls;
    b.innerHTML = '<span class="n-icon">'+n.icon+'</span><p>'+escapeHTML(n.text)+'</p><small>'+escapeHTML(n.small)+'</small>';
    b.addEventListener('click', ()=> openNoteZoom(n, b));
    grid.appendChild(b);
  });
}

/* ============ FEATURED SLIDESHOW (random) ============ */
function refreshFeaturedPool(){
  featuredPool = state.items.filter(i=>i.type==='photo');
  state.order = shuffle(featuredPool.map((_,i)=>i));
  state.pos = 0;
  const wrap = document.querySelector('.featured-wrap');
  const wasEmpty = featuredEmpty;
  featuredEmpty = featuredPool.length===0;
  if(featuredEmpty){
    stopSlide();
    if(wrap) wrap.style.display = 'none';
  } else {
    if(wrap) wrap.style.display = '';
    if(wasEmpty){ setFeatured(state.order[0]); startSlide(); }
  }
}
function setFeatured(poolIdx){
  if(!featuredPool.length || poolIdx==null) return;
  state.currentFeatured = poolIdx;
  const item = featuredPool[poolIdx];
  document.getElementById('featuredImage').src = item.src;
  document.getElementById('featuredNumber').textContent = String(poolIdx+1).padStart(2,'0');
}
function advanceFeatured(){
  if(!state.order.length) return;
  state.pos++;
  if(state.pos>=state.order.length){
    let next = shuffle(featuredPool.map((_,i)=>i));
    if(next.length>1 && state.order.length && next[0]===state.order[state.order.length-1]){
      [next[0],next[1]] = [next[1],next[0]];
    }
    state.order = next; state.pos=0;
  }
  setFeatured(state.order[state.pos]);
}
let slideTimer=null;
function startSlide(){
  clearInterval(slideTimer);
  document.getElementById('featuredCard').classList.add('slideshow-active');
  slideTimer = setInterval(()=>{ if(!document.hidden) advanceFeatured(); }, 4500);
}
function stopSlide(){
  clearInterval(slideTimer);
  slideTimer=null;
  document.getElementById('featuredCard').classList.remove('slideshow-active');
}

/* ============ LIGHTBOX ============ */
function openLightbox(list, idx){
  state.lbList = list; state.lbIndex = idx;
  const lb = document.getElementById('lightbox');
  lb.classList.add('open');
  lb.setAttribute('aria-hidden','false');
  document.body.classList.add('modal-open');
  renderLightbox();
}
function renderLightbox(){
  const item = state.lbList[state.lbIndex];
  if(!item) return;
  const img = document.getElementById('lbImage');
  const vid = document.getElementById('lbVideo');
  vid.pause();
  if(item.type==='video'){
    img.style.display='none';
    vid.style.display='block';
    vid.src = item.src;
  } else {
    vid.style.display='none';
    vid.removeAttribute('src');
    img.style.display='block';
    img.src = item.src;
    img.alt = item.caption || 'Memory';
  }
  document.getElementById('lbCount').textContent = String(state.lbIndex+1).padStart(2,'0');
  document.getElementById('lbTotal').textContent = String(state.lbList.length).padStart(2,'0');
  document.getElementById('lbCaption').textContent = item.caption || '';
}
function closeLightbox(){
  const lb = document.getElementById('lightbox');
  lb.classList.remove('open');
  lb.setAttribute('aria-hidden','true');
  document.body.classList.remove('modal-open');
  document.getElementById('lbVideo').pause();
}
function moveLightbox(d){
  if(!state.lbList.length) return;
  let n = state.lbIndex + d;
  if(n<0) n = state.lbList.length-1;
  if(n>=state.lbList.length) n=0;
  state.lbIndex = n;
  renderLightbox();
}

/* ============ NOTE ZOOM ============ */
function openNoteZoom(note, el){
  const card = document.getElementById('noteZoomCard');
  card.className = 'note-zoom-card '+note.cls;
  document.getElementById('noteZoomIcon').textContent = note.icon;
  document.getElementById('noteZoomText').textContent = note.text;
  document.getElementById('noteZoomSmall').textContent = note.small;
  const r = el.getBoundingClientRect();
  const ox = Math.max(5,Math.min(95, (r.left+r.width/2)/window.innerWidth*100));
  const oy = Math.max(5,Math.min(95, (r.top+r.height/2)/window.innerHeight*100));
  card.style.transformOrigin = ox+'% '+oy+'%';
  const modal = document.getElementById('noteZoom');
  modal.classList.add('open');
  modal.setAttribute('aria-hidden','false');
  document.body.classList.add('modal-open');
}
function closeNoteZoom(){
  const modal = document.getElementById('noteZoom');
  modal.classList.remove('open');
  modal.setAttribute('aria-hidden','true');
  document.body.classList.remove('modal-open');
}

/* ============ PIN GATE ============ */
function initPin(){
  const fields = [...document.querySelectorAll('.pin-digit')];
  const enter = document.getElementById('enterPin');
  const error = document.getElementById('pinError');
  const shell = document.getElementById('pinShell');
  const WARN_ICON = '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z"/><path d="M12 9v4"/><path d="M12 17h.01"/></svg>';

  function clearError(){
    shell.classList.remove('is-error');
    error.textContent = '';
    fields.forEach(x=>{ x.classList.remove('invalid'); x.removeAttribute('aria-invalid'); });
  }
  function showError(msg, allBoxes){
    error.innerHTML = WARN_ICON + '<span>'+escapeHTML(msg)+'</span>';
    shell.classList.add('is-error');
    fields.forEach(x=>{
      const bad = allBoxes || !x.value;
      x.classList.toggle('invalid', bad);
      if(bad) x.setAttribute('aria-invalid','true'); else x.removeAttribute('aria-invalid');
    });
    shell.classList.remove('shake'); void shell.offsetWidth; shell.classList.add('shake');
  }
  function tryPin(){
    const value = fields.map(x=>x.value).join('');
    if(!/^\d{6}$/.test(value)){
      showError('Please enter all 6 numbers.', false);
      const firstEmpty = fields.find(x=>!x.value);
      if(firstEmpty) firstEmpty.focus();
      return;
    }
    if(value !== PIN){
      fields.forEach(x=>x.value='');
      showError('Wrong PIN. The memories stay locked.\u00a0\u2661', true);
      fields[0].focus();
      return;
    }
    clearError();
    unlock();
  }
  fields.forEach((field,i)=>{
    field.addEventListener('input', ()=>{
      clearError();
      field.value = field.value.replace(/\D/g,'').slice(0,1);
      if(field.value && i<fields.length-1) fields[i+1].focus();
    });
    field.addEventListener('keydown', e=>{
      if(e.key==='Backspace') clearError();
      if(e.key==='Backspace' && !field.value && i>0) fields[i-1].focus();
      if(e.key==='Enter') tryPin();
    });
  });
  enter.addEventListener('click', tryPin);

  if(getUnlockedFlag()){ unlock(); }
  else{ fields[0].focus(); }
}
function getUnlockedFlag(){
  try{ return sessionStorage.getItem('memoryUnlocked')==='yes'; }catch(e){ return false; }
}
function setUnlockedFlag(){
  try{ sessionStorage.setItem('memoryUnlocked','yes'); }catch(e){}
}
function unlock(){
  setUnlockedFlag();
  document.getElementById('lockGate').style.display='none';
  document.getElementById('wallContent').classList.add('show');
  startFloatingHearts();
  initRevealObserver();
  attemptAutoplayMusic();
}

/* ============ MUSIC PLAYER ============ */
let bgMusic, musicSeek, musicCurrentTime, musicDuration, musicPlay, musicLoop, playerCard, playerArt, playIconPlay, playIconPause;
function syncSeekBar(){
  const duration = Number.isFinite(bgMusic.duration)?bgMusic.duration:0;
  const current = Number.isFinite(bgMusic.currentTime)?bgMusic.currentTime:0;
  musicSeek.max = duration||0;
  musicSeek.value = Math.min(Math.max(current,0), duration||0);
  const pct = duration>0 ? (current/duration)*100 : 0;
  musicSeek.style.setProperty('--seek-progress', pct+'%');
  musicCurrentTime.textContent = formatTime(current);
  musicDuration.textContent = formatTime(duration);
}
function syncButtons(){
  const playing = !bgMusic.paused && !bgMusic.ended;
  playIconPlay.style.display = playing?'none':'block';
  playIconPause.style.display = playing?'block':'none';
  musicPlay.setAttribute('aria-label', playing?'Pause music':'Play music');
  musicPlay.setAttribute('aria-pressed', String(playing));
  playerCard.classList.toggle('is-playing', playing);
  playerArt.classList.toggle('paused', !playing);
  const looping = bgMusic.loop;
  musicLoop.classList.toggle('is-on', looping);
  musicLoop.setAttribute('aria-label', looping?'Loop music on':'Loop music off');
  musicLoop.setAttribute('aria-pressed', String(looping));
}
async function togglePlay(){
  try{
    if(bgMusic.paused || bgMusic.ended){
      if(bgMusic.ended) bgMusic.currentTime=0;
      await bgMusic.play();
    } else { bgMusic.pause(); }
  }catch(e){}
  syncButtons();
}
function seekMusic(){
  const t = Number(musicSeek.value);
  /* Don't touch activeCue here: updateLyricsFrame() already re-derives it from the new time every
     frame. Pre-setting it to -1 used to backfire whenever the seek target ALSO resolves to -1
     (anywhere before the first line) - the next frame's "did the index change?" check saw -1===-1,
     called it a no-op, and left the previous line frozen on screen instead of clearing it. */
  if(Number.isFinite(t)){ bgMusic.currentTime = t; lastLyricTime=t; syncSeekBar(); }
}
function initMusic(){
  bgMusic = document.getElementById('bgMusic');
  musicSeek = document.getElementById('musicSeek');
  musicCurrentTime = document.getElementById('musicCurrentTime');
  musicDuration = document.getElementById('musicDuration');
  musicPlay = document.getElementById('musicPlay');
  musicLoop = document.getElementById('musicLoop');
  playerCard = document.getElementById('playerCard');
  playerArt = document.getElementById('playerArt');
  playIconPlay = document.getElementById('playIconPlay');
  playIconPause = document.getElementById('playIconPause');

  bgMusic.src = MUSIC_SRC;
  bgMusic.loop = true;
  bgMusic.addEventListener('loadedmetadata', syncSeekBar);
  bgMusic.addEventListener('durationchange', syncSeekBar);
  bgMusic.addEventListener('timeupdate', syncSeekBar);
  bgMusic.addEventListener('play', syncButtons);
  bgMusic.addEventListener('pause', syncButtons);
  bgMusic.addEventListener('ended', ()=>{ syncButtons(); resetLyrics(); });
  musicPlay.addEventListener('click', togglePlay);
  musicLoop.addEventListener('click', ()=>{
    bgMusic.loop = !bgMusic.loop;
    syncButtons();
    if(bgMusic.loop && bgMusic.ended){ bgMusic.currentTime=0; bgMusic.play().catch(()=>{}); }
  });
  musicSeek.addEventListener('input', seekMusic);
  musicSeek.addEventListener('change', seekMusic);
  initVolume();
  syncSeekBar();
  syncButtons();
}
/* ============ VOLUME ============ */
let volumeCtl, musicVolume, musicMute, volIconHigh, volIconLow, volIconMute, lastAudibleVolume=0.8;
const VOLUME_KEY = 'memoryWallVolume';
/* iPhone/iPad Safari never lets a web page change media volume (only the side buttons can), so the control hides itself there. */
function nativeVolumeWorks(){
  try{ const a = new Audio(); a.volume = 0.5; return a.volume === 0.5; }catch(e){ return false; }
}
function paintVolume(){
  const v = bgMusic.volume, pct = Math.round(v*100);
  musicVolume.value = String(pct);
  musicVolume.style.setProperty('--vol', pct+'%');
  musicVolume.setAttribute('aria-valuetext', pct+'%');
  volIconHigh.style.display = v>=0.5 ? 'block' : 'none';
  volIconLow.style.display = (v>0 && v<0.5) ? 'block' : 'none';
  volIconMute.style.display = v===0 ? 'block' : 'none';
  musicMute.setAttribute('aria-label', v===0 ? 'Unmute music' : 'Mute music');
  musicMute.setAttribute('aria-pressed', String(v===0));
}
function setVolume(v, persist){
  v = Math.min(1, Math.max(0, Number(v)||0));
  if(v>0) lastAudibleVolume = v;
  bgMusic.volume = v;
  paintVolume();
  if(persist!==false){ try{ localStorage.setItem(VOLUME_KEY, String(v)); }catch(e){} }
}
function initVolume(){
  volumeCtl = document.getElementById('volumeCtl');
  musicVolume = document.getElementById('musicVolume');
  musicMute = document.getElementById('musicMute');
  volIconHigh = document.getElementById('volIconHigh');
  volIconLow = document.getElementById('volIconLow');
  volIconMute = document.getElementById('volIconMute');
  if(!nativeVolumeWorks()){ volumeCtl.hidden = true; return; } // still hidden: nothing above needs wiring
  let saved = 1;
  try{
    const s = parseFloat(localStorage.getItem(VOLUME_KEY));
    if(Number.isFinite(s)) saved = Math.min(1, Math.max(0, s));
  }catch(e){}
  setVolume(saved, false);
  musicVolume.addEventListener('input', ()=> setVolume(Number(musicVolume.value)/100));
  musicMute.addEventListener('click', ()=>{
    setVolume(bgMusic.volume>0 ? 0 : (lastAudibleVolume||0.8));
    const open = volumeCtl.classList.toggle('expanded');
    musicMute.setAttribute('aria-expanded', String(open));
  });
  document.addEventListener('click', e=>{
    if(volumeCtl.classList.contains('expanded') && !volumeCtl.contains(e.target)){
      volumeCtl.classList.remove('expanded');
      musicMute.setAttribute('aria-expanded','false');
    }
  });
  /* Scrolling the mouse wheel while hovering the volume control also changes the volume. */
  volumeCtl.addEventListener('wheel', e=>{
    e.preventDefault();
    const unit = e.deltaMode===1 ? 0.03 : (e.deltaMode===2 ? 0.3 : 0.0008);
    setVolume(bgMusic.volume - e.deltaY*unit);
  }, {passive:false});
}
function attemptAutoplayMusic(){
  if(!bgMusic) return;
  const p = bgMusic.play();
  if(p && typeof p.catch==='function'){
    p.catch(()=>{
      if(!document.getElementById('musicFallback')){
        const b = document.createElement('button');
        b.id='musicFallback'; b.className='music-fallback'; b.type='button';
        b.textContent='♪ Tap to start the music';
        b.addEventListener('click', ()=>{ bgMusic.play().then(()=>{ b.remove(); syncButtons(); }).catch(()=>{}); });
        document.body.appendChild(b);
      }
      syncButtons();
    });
  }
}

/* ============ KARAOKE LYRICS (word-level, syllable-weighted) ============ */
let liveLyric, activeCue=-1, lastLyricTime=0;

/* Base timing shift in seconds: + shows the lyrics later, − earlier.
   You can also nudge it live while the page is open: ] = later, [ = earlier (0.05s per press), \ = reset. */
const LYRIC_OFFSET = 0.0;
/* One sung syllable lasts about this long. A line's highlight runs for (syllables × this) and never past the
   moment the next line starts (minus LYRIC_REST_SEC), so it never crawls across an instrumental gap.
   To pin one line exactly, add s (sung start) and/or e (sung end), in seconds, to its entry in lyricCues. */
const LYRIC_SYLLABLE_SEC = 0.40;
const LYRIC_REST_SEC = 0.30;
const LYRIC_MIN_LINE_SEC = 1.0;
const LYRIC_LAST_LINE_SEC = 5.0;
const LYRIC_NUDGE_KEY = 'memoryWallLyricNudge';
const INTRO_LYRIC = 'tap play, and listen with me \u2661';

let lyricNudge = 0, lyricLines = [], lyricWordEls = [], lyricWordProg = [], lyricsEverActive = false;
const lyricClock = {rep:0, perf:0};

/* Filipino syllables: every vowel letter is a syllable (the u in "qui" is silent); "mga" is sung "manga", "ng" as "nang". */
function countSyllables(word){
  const w = word.toLowerCase().replace(/[^a-z\u00f1]/g,'');
  if(!w) return 0;
  if(w==='mga') return 2;
  if(w==='ng') return 1;
  let n = 0;
  for(let i=0;i<w.length;i++){
    if('aeiou'.includes(w[i]) && !(w[i]==='u' && w[i-1]==='q')) n++;
  }
  return Math.max(1, n);
}
function buildLyricTimeline(){
  lyricLines = lyricCues.map((cue,i)=>{
    const words = cue.text.split(/\s+/).filter(Boolean);
    const weights = words.map(w=>Math.max(0.5, countSyllables(w)));
    const total = weights.reduce((a,b)=>a+b, 0) || 1;
    const next = lyricCues[i+1];
    const start = (typeof cue.s==='number') ? cue.s : cue.t;
    let end;
    if(typeof cue.e==='number'){
      end = cue.e;
    } else {
      const room = next ? (next.t - start - LYRIC_REST_SEC) : LYRIC_LAST_LINE_SEC;
      end = start + Math.min(Math.max(total*LYRIC_SYLLABLE_SEC, LYRIC_MIN_LINE_SEC), Math.max(room, 0.5));
    }
    if(end <= start) end = start + LYRIC_MIN_LINE_SEC;
    let acc = 0;
    const timed = words.map((text,k)=>{
      const a = start + (end-start)*(acc/total);
      acc += weights[k];
      const b = start + (end-start)*(acc/total);
      return {text, a, b};
    });
    return {t:cue.t, start, end, words:timed};
  });
}
function loadLyricNudge(){
  try{
    const v = parseFloat(localStorage.getItem(LYRIC_NUDGE_KEY));
    if(Number.isFinite(v)) lyricNudge = Math.max(-2, Math.min(2, v));
  }catch(e){}
}
function nudgeLyrics(delta){
  lyricNudge = delta===0 ? 0 : Math.max(-2, Math.min(2, Math.round((lyricNudge+delta)*100)/100));
  try{ localStorage.setItem(LYRIC_NUDGE_KEY, String(lyricNudge)); }catch(e){}
  const total = LYRIC_OFFSET + lyricNudge;
  showToast(total===0 ? 'Lyrics timing: original' : 'Lyrics timing: '+(total>0?'+':'\u2212')+Math.abs(total).toFixed(2)+'s');
}
/* Media clock for the lyrics. Some browsers only refresh audio.currentTime in coarse steps, so between two
   readings the time is advanced with performance.now() (never more than 0.25s) to keep the highlight smooth. */
function lyricMediaTime(){
  const a = bgMusic;
  const cur = Number(a.currentTime) || 0;
  const now = performance.now();
  if(a.paused || a.ended || a.seeking || cur !== lyricClock.rep){
    lyricClock.rep = cur;
    lyricClock.perf = now;
    return cur;
  }
  return cur + Math.min(0.25, (now - lyricClock.perf)/1000 * (a.playbackRate||1));
}
function resetLyrics(){
  activeCue=-1; lastLyricTime=0;
  if(lyricsEverActive){
    /* Rewound into the instrumental intro (not the pristine first-load state anymore): show it's
       coming, not a leftover "tap play" prompt that no longer makes sense once you're already listening. */
    liveLyric.className='lyrics-line idle intro';
    liveLyric.innerHTML = '<span class="intro-dots" aria-hidden="true"><span></span><span></span><span></span></span><span class="sr-only">Instrumental intro</span>';
  } else {
    liveLyric.className='lyrics-line idle';
    liveLyric.innerHTML = '<span class="base">'+escapeHTML(INTRO_LYRIC)+'</span>';
  }
}
/* One highlight layer per word, so a line that wraps onto two rows fills row by row instead of both at once. */
function showLyricLine(idx){
  const line = lyricLines[idx];
  liveLyric.className = 'lyrics-line';
  liveLyric.textContent = '';
  lyricWordEls = [];
  lyricWordProg = [];
  line.words.forEach((w,k)=>{
    if(k>0) liveLyric.appendChild(document.createTextNode(' '));
    const wrap = document.createElement('span');
    wrap.className = 'lw';
    const base = document.createElement('span');
    base.className = 'base';
    base.textContent = w.text;
    const fill = document.createElement('span');
    fill.className = 'fill';
    fill.setAttribute('aria-hidden','true');
    fill.textContent = w.text;
    wrap.appendChild(base);
    wrap.appendChild(fill);
    liveLyric.appendChild(wrap);
    lyricWordEls.push(fill);
    lyricWordProg.push(0);
  });
}
function updateLyricsFrame(){
  requestAnimationFrame(updateLyricsFrame);
  if(!bgMusic || !lyricLines.length) return;
  const rawTime = lyricMediaTime();
  if(!lyricsEverActive && rawTime > 0.05) lyricsEverActive = true;
  lastLyricTime = rawTime;
  const t = Math.max(0, rawTime - (LYRIC_OFFSET + lyricNudge));
  let idx = -1;
  for(let i=lyricLines.length-1;i>=0;i--){ if(t>=lyricLines[i].t){ idx=i; break; } }
  if(idx!==activeCue){
    activeCue = idx;
    if(idx>=0) showLyricLine(idx); else resetLyrics();
  }
  if(idx<0) return;
  const words = lyricLines[idx].words;
  for(let k=0;k<words.length;k++){
    const w = words[k];
    const span = w.b - w.a;
    const p = span>0 ? Math.min(1, Math.max(0, (t-w.a)/span)) : (t>=w.a ? 1 : 0);
    if(p!==lyricWordProg[k] && (Math.abs(p-lyricWordProg[k])>0.004 || p===0 || p===1)){
      lyricWordProg[k] = p;
      lyricWordEls[k].style.clipPath = 'inset(0 '+((1-p)*100).toFixed(2)+'% 0 0)';
    }
  }
}

/* ============ REVEAL ON SCROLL ============ */
function initRevealObserver(){
  const els = document.querySelectorAll('.reveal');
  if(!('IntersectionObserver' in window)){ els.forEach(el=>el.classList.add('in')); return; }
  const io = new IntersectionObserver((entries)=>{
    entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); } });
  }, {threshold:0.12});
  els.forEach(el=>io.observe(el));
}

/* ============ FLOATING HEARTS ============ */
let heartsTimer=null;
function startFloatingHearts(){
  const container = document.getElementById('floatingHearts');
  const chars = ['♡','♥','🌷'];
  function spawn(){
    const el = document.createElement('span');
    el.className='fh';
    el.textContent = chars[Math.floor(Math.random()*chars.length)];
    el.style.left = (2+Math.random()*96)+'%';
    el.style.animationDuration = (7+Math.random()*5)+'s';
    el.style.fontSize = (14+Math.random()*14)+'px';
    container.appendChild(el);
    setTimeout(()=>el.remove(), 13000);
  }
  clearInterval(heartsTimer);
  heartsTimer = setInterval(spawn, 2200);
  spawn();
}

/* ============ UPLOAD MODAL ============ */
let uploadModal, dropZone, fileInput, filePreviewList, uploadSubmit, uploadAlbumChips, uploadCaption;
function openUploadModal(){
  state.uploadFiles = [];
  state.uploadCats = new Set();
  uploadCaption.value='';
  document.getElementById('uploadNewAlbumRow').style.display='none';
  document.getElementById('uploadNewAlbumInput').value='';
  renderFilePreviews();
  renderUploadChips();
  uploadModal.classList.add('open');
  uploadModal.setAttribute('aria-hidden','false');
  document.body.classList.add('modal-open');
}
function closeUploadModal(){
  uploadModal.classList.remove('open');
  uploadModal.setAttribute('aria-hidden','true');
  document.body.classList.remove('modal-open');
}
function renderUploadChips(){
  uploadAlbumChips.innerHTML='';
  Object.keys(state.categories).forEach(id=>{
    const chip = document.createElement('button');
    chip.type='button';
    chip.className='album-chip'+(state.uploadCats.has(id)?' selected':'');
    chip.textContent = state.categories[id];
    chip.addEventListener('click', ()=>{
      if(state.uploadCats.has(id)) state.uploadCats.delete(id); else state.uploadCats.add(id);
      renderUploadChips();
    });
    uploadAlbumChips.appendChild(chip);
  });
  const newChip = document.createElement('button');
  newChip.type='button';
  newChip.className='album-chip chip-new';
  newChip.textContent='+ New album';
  newChip.addEventListener('click', ()=>{
    document.getElementById('uploadNewAlbumRow').style.display='flex';
    document.getElementById('uploadNewAlbumInput').focus();
  });
  uploadAlbumChips.appendChild(newChip);
}
function addFiles(fileList){
  Array.from(fileList).forEach(file=>{
    if(!/^image\/|^video\//.test(file.type)) return;
    let url;
    try{ url = URL.createObjectURL(file); }catch(e){ return; }
    state.uploadFiles.push({file, url, type:file.type.startsWith('video')?'video':'photo'});
  });
  renderFilePreviews();
}
function renderFilePreviews(){
  filePreviewList.innerHTML='';
  state.uploadFiles.forEach((f,idx)=>{
    const wrap = document.createElement('div');
    wrap.className='file-preview';
    const media = document.createElement(f.type==='video'?'video':'img');
    media.src = f.url;
    if(f.type==='video') media.muted=true;
    wrap.appendChild(media);
    const rm = document.createElement('button');
    rm.type='button'; rm.className='fp-remove'; rm.textContent='×';
    rm.setAttribute('aria-label','Remove');
    rm.addEventListener('click', (e)=>{ e.stopPropagation(); state.uploadFiles.splice(idx,1); renderFilePreviews(); });
    wrap.appendChild(rm);
    filePreviewList.appendChild(wrap);
  });
  uploadSubmit.disabled = state.uploadFiles.length===0;
}
function initUpload(){
  uploadModal = document.getElementById('uploadModal');
  dropZone = document.getElementById('dropZone');
  fileInput = document.getElementById('fileInput');
  filePreviewList = document.getElementById('filePreviewList');
  uploadSubmit = document.getElementById('uploadSubmit');
  uploadAlbumChips = document.getElementById('uploadAlbumChips');
  uploadCaption = document.getElementById('uploadCaption');

  dropZone.addEventListener('click', ()=>fileInput.click());
  dropZone.addEventListener('keydown', e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); fileInput.click(); } });
  fileInput.addEventListener('change', ()=>{ addFiles(fileInput.files); fileInput.value=''; });
  ['dragenter','dragover'].forEach(ev=> dropZone.addEventListener(ev, e=>{ e.preventDefault(); dropZone.classList.add('drag-over'); }));
  ['dragleave','drop'].forEach(ev=> dropZone.addEventListener(ev, e=>{ e.preventDefault(); dropZone.classList.remove('drag-over'); }));
  dropZone.addEventListener('drop', e=>{ if(e.dataTransfer && e.dataTransfer.files) addFiles(e.dataTransfer.files); });

  document.getElementById('openUpload').addEventListener('click', openUploadModal);
  document.getElementById('uploadClose').addEventListener('click', closeUploadModal);
  uploadModal.addEventListener('click', e=>{ if(e.target===uploadModal) closeUploadModal(); });

  uploadSubmit.addEventListener('click', async ()=>{
    if(!state.uploadFiles.length) return;
    uploadSubmit.disabled = true;
    uploadSubmit.textContent = 'Adding…';
    const caption = uploadCaption.value.trim();
    const cats = Array.from(state.uploadCats);
    const addedIds = [];
    for(const f of state.uploadFiles){
      const id = uid();
      const record = {id, type:f.type, blob:f.file, categories:cats, caption, addedAt:Date.now()};
      await idbPut('items', record);
      state.items.push({id, type:f.type, src:f.url, categories:cats, caption, isSeed:false});
      addedIds.push(id);
    }
    lastAddedIds = new Set(addedIds);
    renderFilters();
    renderGrid();
    updateCountBadge();
    refreshFeaturedPool();
    closeUploadModal();
    uploadSubmit.disabled=false;
    uploadSubmit.textContent='Add to the wall 🌷';
    showToast(addedIds.length===1 ? 'Added to your wall 🌷' : addedIds.length+' memories added 🌷');
    const panel = document.querySelector('.photo-panel');
    if(panel) panel.scrollIntoView({behavior:'smooth', block:'start'});
  });
}

/* ============ GLOBAL MODAL / NAV HANDLERS ============ */
function initGlobalHandlers(){
  document.getElementById('lbClose').addEventListener('click', closeLightbox);
  document.getElementById('lbDelete').addEventListener('click', ()=> deleteItem(state.lbList[state.lbIndex]));
  document.getElementById('lbPrev').addEventListener('click', ()=>moveLightbox(-1));
  document.getElementById('lbNext').addEventListener('click', ()=>moveLightbox(1));
  document.getElementById('lightbox').addEventListener('click', e=>{ if(e.target.id==='lightbox') closeLightbox(); });
  document.getElementById('noteZoomClose').addEventListener('click', closeNoteZoom);
  document.getElementById('noteZoom').addEventListener('click', e=>{ if(e.target.id==='noteZoom') closeNoteZoom(); });
  document.addEventListener('keydown', e=>{
    if(document.getElementById('lightbox').classList.contains('open')){
      if(e.key==='Escape') closeLightbox();
      if(e.key==='ArrowLeft') moveLightbox(-1);
      if(e.key==='ArrowRight') moveLightbox(1);
    }
    if(document.getElementById('noteZoom').classList.contains('open') && e.key==='Escape') closeNoteZoom();
    if(uploadModal && uploadModal.classList.contains('open') && e.key==='Escape') closeUploadModal();
    if(document.getElementById('confirmModal').classList.contains('open') && e.key==='Escape') closeConfirm(false);
    if(document.getElementById('albumDeleteModal').classList.contains('open') && e.key==='Escape') closeAlbumDelete(null);
    /* Lyric timing fine-tune: ] later, [ earlier, \ reset (ignored while typing in a text field). */
    const tag = e.target && e.target.tagName;
    const typing = tag==='TEXTAREA' || (tag==='INPUT' && e.target.type!=='range');
    if(!typing && !e.ctrlKey && !e.metaKey && !e.altKey && document.getElementById('wallContent').classList.contains('show')){
      if(e.key==='[') nudgeLyrics(-0.05);
      else if(e.key===']') nudgeLyrics(0.05);
      else if(e.key==='\\') nudgeLyrics(0);
    }
    if(volumeCtl && e.key==='Escape' && (volumeCtl.classList.contains('expanded') || (document.activeElement && volumeCtl.contains(document.activeElement)))){
      volumeCtl.classList.remove('expanded');
      musicMute.setAttribute('aria-expanded','false');
      if(document.activeElement && volumeCtl.contains(document.activeElement)) document.activeElement.blur();
    }
  });
  document.getElementById('againBtn').addEventListener('click', ()=>{
    window.scrollTo({top:0, behavior:'smooth'});
  });
  document.getElementById('nextFeatured').addEventListener('click', ()=>{ stopSlide(); advanceFeatured(); });
  document.getElementById('featuredImage').addEventListener('click', ()=>{
    stopSlide();
    if(featuredPool.length) openLightbox(featuredPool, state.currentFeatured);
  });
  document.getElementById('newAlbumConfirm').addEventListener('click', async ()=>{
    const input = document.getElementById('newAlbumInput');
    const name = input.value.trim();
    if(name){ await createAlbum(name); input.value=''; document.getElementById('newAlbumRow').style.display='none'; }
  });
  document.getElementById('newAlbumCancel').addEventListener('click', ()=>{
    document.getElementById('newAlbumInput').value='';
    document.getElementById('newAlbumRow').style.display='none';
  });
  document.getElementById('newAlbumInput').addEventListener('keydown', e=>{
    if(e.key==='Enter') document.getElementById('newAlbumConfirm').click();
  });
  document.getElementById('confirmCancel').addEventListener('click', ()=>closeConfirm(false));
  document.getElementById('confirmOk').addEventListener('click', ()=>closeConfirm(true));
  document.getElementById('confirmModal').addEventListener('click', e=>{ if(e.target.id==='confirmModal') closeConfirm(false); });
  document.getElementById('albumDeleteOnly').addEventListener('click', ()=>closeAlbumDelete('only'));
  document.getElementById('albumDeleteAll').addEventListener('click', ()=>closeAlbumDelete('all'));
  document.getElementById('albumDeleteCancel').addEventListener('click', ()=>closeAlbumDelete(null));
  document.getElementById('albumDeleteModal').addEventListener('click', e=>{ if(e.target.id==='albumDeleteModal') closeAlbumDelete(null); });
  document.getElementById('uploadNewAlbumConfirm').addEventListener('click', async ()=>{
    const input = document.getElementById('uploadNewAlbumInput');
    const name = input.value.trim();
    if(name){
      const id = await createAlbum(name);
      if(id) state.uploadCats.add(id);
      input.value='';
      document.getElementById('uploadNewAlbumRow').style.display='none';
      renderUploadChips();
    }
  });
  document.getElementById('uploadNewAlbumCancel').addEventListener('click', ()=>{
    document.getElementById('uploadNewAlbumInput').value='';
    document.getElementById('uploadNewAlbumRow').style.display='none';
  });
  document.getElementById('uploadNewAlbumInput').addEventListener('keydown', e=>{
    if(e.key==='Enter') document.getElementById('uploadNewAlbumConfirm').click();
  });
}

/* ============ INIT ============ */
function init(){
  document.getElementById('decoImg1').src = EMOJI1_SRC;
  document.getElementById('decoImg2').src = EMOJI2_SRC;
  document.getElementById('playerArtImg').src = EMOJI2_SRC;
  document.getElementById('bgVideo').src = LOCK_OVERLAY_SRC;
  liveLyric = document.getElementById('liveLyric');

  buildSeedState();
  renderFilters();
  renderGrid();
  renderNotes();
  updateCountBadge();
  refreshFeaturedPool();
  if(featuredPool.length){ setFeatured(state.order[0]); startSlide(); }

  initMusic();
  initUpload();
  initGlobalHandlers();
  loadLyricNudge();
  buildLyricTimeline();
  resetLyrics();
  requestAnimationFrame(updateLyricsFrame);
  loadUploaded();

  initPin();
}
init();
